package com.simibubi.create.test;

import com.simibubi.create.content.equipment.bell.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.level.block.Blocks;

public class SoulPulseGameTests {
    private static final BlockPos P=new BlockPos(4,4,4);
    @GameTest public void sourceLayersAreUniqueSymmetricAndBounded(GameTestHelper h) { var all=new java.util.HashSet<BlockPos>();for(int i=0;i<SoulPulseEffect.MAX_DISTANCE;i++){int layer=i;var list=SoulPulseEffect.getLayer(i).toList();h.assertTrue(all.addAll(list),"Each layer contributes positions");h.assertValueEqual(new java.util.HashSet<>(list).size(),list.size(),"No duplicate reflected zero coordinates");for(var p:list){h.assertValueEqual(Math.max(1,(int)Math.round(Math.sqrt(p.distSqr(BlockPos.ZERO)))),layer+1,"Rounded source radius");h.assertTrue(list.contains(new BlockPos(-p.getX(),-p.getY(),-p.getZ())),"Reflection symmetry");}}h.assertValueEqual(SoulPulseEffect.getLayer(0).count(),19L,"Original first shell includes origin and edge diagonals");h.assertTrue(SoulPulseEffect.getLayer(-1).findAny().isEmpty()&&SoulPulseEffect.getLayer(11).findAny().isEmpty(),"Outside table skipped");h.succeed(); }
    @GameTest public void invalidPacketAndEffectRadiiAreRejected(GameTestHelper h) { for(int value:new int[]{-1,0,12,Integer.MAX_VALUE}){boolean packet=false,effect=false;try{new SoulPulseEffectPacket(BlockPos.ZERO,value,false);}catch(IllegalArgumentException expected){packet=true;}try{new SoulPulseEffect(BlockPos.ZERO,value,false);}catch(IllegalArgumentException expected){effect=true;}h.assertTrue(packet&&effect,"Bounded layer allocation/iteration");}h.succeed(); }
    @GameTest public void spawnPreviewRequiresGroundAndClearShortBody(GameTestHelper h) { var at=h.absolutePos(P);h.assertFalse(SoulPulseEffect.canSpawnSoulAt(h.getLevel(),at,true),"No ground");h.setBlock(P.below(),Blocks.STONE);h.assertTrue(SoulPulseEffect.canSpawnSoulAt(h.getLevel(),at,true),"Solid ground and empty body");h.setBlock(P,Blocks.STONE);h.assertFalse(SoulPulseEffect.canSpawnSoulAt(h.getLevel(),at,true),"Occupied position");h.succeed(); }
    @GameTest public void spawnPreviewSkipsFluidsAndUnknownChunks(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);h.setBlock(P,Blocks.WATER);h.assertFalse(SoulPulseEffect.canSpawnSoulAt(h.getLevel(),h.absolutePos(P),true),"Liquid is not dry spawn position");var far=new BlockPos(2000000,60,2000000);h.assertFalse(SoulPulseEffect.canSpawnSoulAt(h.getLevel(),far,true),"Unknown chunk skipped");h.assertTrue(h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Preview creates no ticket");h.succeed(); }
    @GameTest(maxTicks=60) public void blockLightSuppressesDarkPreview(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);h.setBlock(P.east(),Blocks.GLOWSTONE);h.succeedWhen(()->h.assertTrue(!SoulPulseEffect.isDark(h.getLevel(),h.absolutePos(P))&&!SoulPulseEffect.canSpawnSoulAt(h.getLevel(),h.absolutePos(P),false)&&SoulPulseEffect.canSpawnSoulAt(h.getLevel(),h.absolutePos(P),true),"Light filter and ignoreLight preserve source distinction")); }
    @GameTest public void pulseSkipsEmptyLayersAndExpiresAfterSourceWait(GameTestHelper h) { var pulse=new SoulPulseEffect(h.absolutePos(P.above(10)),3,false);for(int i=0;i<6;i++)pulse.tick(h.getLevel());h.assertValueEqual(pulse.currentLayerIdx(),2,"Empty shells advanced without repeated wait");h.assertFalse(pulse.finished(),"Source waiting interval still active");for(int i=0;i<100;i++)pulse.tick(h.getLevel());h.assertTrue(pulse.finished(),"Finite source waiting interval");h.succeed(); }
    @GameTest public void nonOverlappingPulsesShareAndReleaseOccupiedPositions(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);var handler=new SoulPulseEffectHandler();handler.addPulse(new SoulPulseEffect(h.absolutePos(P),1,false));handler.addPulse(new SoulPulseEffect(h.absolutePos(P),1,false));for(int i=0;i<6;i++)handler.tick(h.getLevel());h.assertValueEqual(handler.occupiedPositions(),1,"Duplicate pulses reserve a cell once");for(int i=0;i<110;i++)handler.tick(h.getLevel());h.assertTrue(handler.occupiedPositions()==0&&handler.activePulses()==0,"Completed effects release reservations");h.succeed(); }
    @GameTest public void overlappingPulseDoesNotReserveAndRefreshDropsAllState(GameTestHelper h) { h.setBlock(P.below(),Blocks.STONE);var handler=new SoulPulseEffectHandler();handler.addPulse(new SoulPulseEffect(h.absolutePos(P),1,true));for(int i=0;i<6;i++)handler.tick(h.getLevel());h.assertTrue(handler.activePulses()==1&&handler.occupiedPositions()==0,"Overlap path has no reservation");handler.refresh();h.assertTrue(handler.activePulses()==0&&handler.occupiedPositions()==0,"Level lifecycle clears state");h.succeed(); }
    @GameTest public void heldWarmupAndLiteralSourceCadenceArePreserved(GameTestHelper h) { var warm=new HauntedBellPulser.Warmup();long now=1_000_000_000L;for(int i=0;i<9;i++)h.assertFalse(warm.tick(now+i*1_000_000L,i),"Ten-tick source warmup");h.assertTrue(warm.tick(now+9_000_000L,16),"First pulse even at modulo-zero tick");int pulses=0;for(int i=0;i<8;i++)if(warm.tick(now+10_000_000L+i*1_000_000L,24+i))pulses++;h.assertValueEqual(pulses,7,"Source condition is !=0, not ==0");h.assertFalse(warm.tick(now+500_000_000L,33),"250ms inactivity restarts warmup");h.succeed(); }
}
